import subprocess
import threading
import time
import sys
from datetime import datetime
from queue import Queue
from typing import List, Dict, Tuple

def run_ping(hostname: str) -> Tuple[int, str]:
    try:
        result = subprocess.run(
            ['ping', '-c', '1', hostname],
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            timeout=5
        )
        return result.returncode, result.stdout + result.stderr
    except subprocess.CalledProcessError as e:
        return e.returncode, str(e)
    except Exception as e:
        return 1, f"Error: {str(e)}"

def worker(hostnames: Queue, results: Dict[str, Tuple[int, str]], max_workers: int = 4):
    while True:
        hostname = hostnames.get()
        if hostname is None:
            break
        try:
            status, output = run_ping(hostname)
            results[hostname] = (status, output)
        finally:
            hostnames.task_done()

def generate_report(results: Dict[str, Tuple[int, str]]) -> str:
    html = ['<html><head><title>Host Check Report</title></head><body>']
    html.append('<table border="1">')
    html.append('<tr><th>Host</th><th>Status</th><th>Output</th></tr>')

    for hostname, (status, output) in results.items():
        html.append(f'<tr><td>{hostname}</td><td>{"OK" if status == 0 else "FAILED"}</td><td>{output}</td></tr>')

    html.append('</table></body></html>')
    return '\n'.join(html)

def generate_log(results: Dict[str, Tuple[int, str]]) -> List[str]:
    log_lines = []
    for hostname, (status, _) in results.items():
        timestamp = datetime.utcnow().strftime('%Y-%m-%dT%H:%M:%SZ')
        log_lines.append(f'{timestamp} {hostname} {"OK" if status == 0 else "FAILED"}')
    return log_lines

def main():
    try:
        hostnames = []
        for line in sys.stdin:
            stripped = line.strip()
            if stripped:
                hostnames.append(stripped)

        if not hostnames:
            print("No hostnames provided", file=sys.stderr)
            sys.exit(1)

        results = {}
        hostnames_queue = Queue()
        for hostname in hostnames:
            hostnames_queue.put(hostname)

        threads = []
        for _ in range(min(4, len(hostnames))):
            t = threading.Thread(target=worker, args=(hostnames_queue, results))
            threads.append(t)
            t.start()

        hostnames_queue.join()

        for _ in range(min(4, len(hostnames))):
            hostnames_queue.put(None)

        for t in threads:
            t.join()

        report_html = generate_report(results)
        with open('report.html', 'w') as f:
            f.write(report_html)

        log_lines = generate_log(results)
        with open('run.log', 'w') as f:
            for line in log_lines:
                f.write(line + '\n')

    except Exception as e:
        print(f"Error: {str(e)}", file=sys.stderr)
        sys.exit(1)

if __name__ == '__main__':
    main()

import concurrent.futures
import subprocess
import sys
import os
from datetime import datetime

def run_ping(hostname):
    try:
        result = subprocess.run(['ping', '-c', '1', hostname], capture_output=True, text=True)
        return (hostname, result.returncode, result.stdout)
    except Exception:
        return (hostname, 1, "")

def generate_report(hosts, results):
    try:
        with open('report.html', 'w') as f:
            f.write('''<!DOCTYPE html>
<html>
<head>
    <title>Hostname Check Report</title>
    <style>
        table { border-collapse: collapse; width: 100%; }
        th, td { border: 1px solid #ddd; padding: 8px; text-align: left; }
        th { background-color: #f2f2f2; }
    </style>
</head>
<body>
    <table>
        <tr>
            <th>Host</th>
            <th>Status</th>
            <th>Output</th>
        </tr>
''')
            for hostname, status, output in results:
                f.write(f'''        <tr>
            <td>{hostname}</td>
            <td>{'OK' if status == 0 else 'FAILED'}</td>
            <td>{output}</td>
        </tr>
''')
            f.write('''    </table>
</body>
</html>
''')
    except Exception:
        sys.stderr.write("Failed to generate report.html\n")
        sys.exit(1)

def generate_log(hosts, results):
    try:
        with open('run.log', 'w') as f:
            for hostname, status, _ in results:
                f.write(f"{hostname} {'OK' if status == 0 else 'FAILED'}\n")
    except Exception:
        sys.stderr.write("Failed to generate run.log\n")
        sys.exit(1)

def main():
    try:
        hostnames = [line.strip() for line in sys.stdin if line.strip()]
        if not hostnames:
            return

        with concurrent.futures.ThreadPoolExecutor(max_workers=4) as executor:
            futures = [executor.submit(run_ping, hostname) for hostname in hostnames]
            results = []
            for future in concurrent.futures.as_completed(futures):
                hostname, status, output = future.result()
                results.append((hostname, status, output))

        generate_report(hostnames, results)
        generate_log(hostnames, results)
    except Exception:
        sys.stderr.write("An error occurred\n")
        sys.exit(1)

if __name__ == "__main__":
    main()
